// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · İtalyan, İspanyol, İskandinav, Balkan ve Türk dünyası edebiyatı klasikleri (Dante, Cervantes, Borges, Márquez, Calvino, Eco, Aytmatov, Andrić) (kolay).
const ozLiterature18Kolay = <(String, String, List<String>, String)>[
  ('Dante Alighieri\'nin öte dünya yolculuğunu anlattığı "İlahi Komedya" adlı ölümsüz eseri hangi üç ana bölümden oluşmaktadır?', 'Cehennem, Araf ve Cennet', ['Cehennem, Yeryüzü ve Gökyüzü', 'Karanlık, Aydınlık ve Sonsuzluk', 'Günah, Tövbe ve Kurtuluş Kapısı'], 'İlahi Komedya sırasıyla Inferno (Cehennem), Purgatorio (Araf) ve Paradiso (Cennet) olmak üzere üç ana bölümden (cantica) oluşur.'),
  ('Dante\'nin "İlahi Komedya" eserinde Cehennem ve Araf yolculuğu boyunca ona rehberlik eden Antik Romalı şair kimdir?', 'Vergilius', ['Ovidius Naso', 'Horatius Flaccus', 'Marcus Lucanus'], 'Dante\'ye akıl ve insan bilgisini simgeleyen Romalı şair Vergilius, Cehennem ve Araf katmanlarında rehberlik eder.'),
  ('Dante Alighieri\'nin "Yeni Hayat" (Vita Nuova) ve "İlahi Komedya" eserlerinde ilahi aşkın ve kurtuluşun simgesi olarak yücelttiği esin kaynağı kimdir?', 'Beatrice', ['Laura de Noves', 'Fiammetta', 'Angelica'], 'Dante\'nin çocuk yaşta görüp ömrü boyunca idealize ettiği Beatrice Portinari, Cennet bölümünde şaire bizzat rehberlik eder.'),
  ('Rönesans hümanizminin kurucu babası sayılan ve "Canzoniere" (Türküler Kitabı) adlı eseriyle sone nazım biçimini Avrupa edebiyatında zirveye taşıyan İtalyan şair kimdir?', 'Francesco Petrarca', ['Giovanni Boccaccio', 'Giacomo Leopardi', 'Ugo Foscolo'], 'Petrarca, antik elyazmalarını derlemesiyle hümanizmin öncüsü olmuş ve sone biçimini İtalyan ve Avrupa şiirinin temel kalıbı haline getirmiştir.'),
  ('Francesco Petrarca\'nın "Canzoniere" adlı şiir kitabındaki yüzlerce sonesinde ölümsüzleştirdiği büyük ve ulaşılmaz aşkının adı nedir?', 'Laura', ['Beatrice', 'Fiammetta', 'Silvia'], 'Petrarca 1327 yılında Avignon\'daki Sainte-Claire Kilisesi\'nde gördüğü Laura\'ya duyduğu aşkı hem onun sağlığında hem ölümünden sonra şiirleştirmiştir.'),
  ('Giovanni Boccaccio\'nun Avrupa edebiyatında modern öykücülüğün (novella) başlangıcı kabul edilen başyapıtı aşağıdakilerden hangisidir?', 'Decameron', ['Heptameron', 'Canterbury Hikayeleri', 'Yüz Bir Gece Masalları'], 'Boccaccio\'nun 1348-1353 yılları arasında kaleme aldığı Decameron, gerçekçi gözlemleri ve dünyevi temalarıyla modern öykü türünün kurucu metnidir.'),
  ('Boccaccio\'nun "Decameron" adlı eserinde on gencin Floransa\'dan kaçıp kırsaldaki bir villaya sığınarak birbirlerine öyküler anlatmasına yol açan tarihsel felaket nedir?', '1348 Büyük Veba Salgını', ['Kutsal Roma İmparatoru\'nun Floransa kuşatması', 'Arno Nehri\'nin taşmasıyla yaşanan büyük sel', 'Guelfolar ile Ghibellinolar arasındaki kanlı iç savaş'], '1348\'de Floransa nüfusunun büyük bölümünü yok eden Kara Veba salgını, eserin çerçeve öyküsünün tarihsel ve dramatik arka planını oluşturur.'),
  ('İtalyan Rönesans şairi Ludovico Ariosto\'nun Şarlman dönemi şövalyelerini, aşkı ve büyülü serüvenleri anlattığı ünlü epik şiiri hangisidir?', 'Çılgın Orlando (Orlando Furioso)', ['Kurtarılmış Kudüs (Gerusalemme Liberata)', 'Aşık Orlando (Orlando Innamorato)', 'Dev Morgante (Il Morgante)'], 'Ariosto\'nun Ferrara sarayında yazdığı Orlando Furioso, Rönesans İtalyası\'nın en parlak ve hayal gücü en zengin şövalye destanıdır.'),
  ('Geç Rönesans dönemi İtalyan şairi Torquato Tasso\'nun Birinci Haçlı Seferi\'ni ve Kudüs kuşatmasını konu alan ünlü epik destanı hangisidir?', 'Kurtarılmış Kudüs (Gerusalemme Liberata)', ['Çılgın Orlando (Orlando Furioso)', 'Fethedilmiş Kudüs (Gerusalemme Conquistata)', 'Aminta (Pastoral Drama)'], 'Tasso\'nun 1581\'de yayımlanan başyapıtı Kurtarılmış Kudüs, tarihsel Haçlı kuşatmasını lirik aşk ve büyü motifleriyle birleştiren büyük bir destandır.'),
  ('1934 yılında Nobel Edebiyat Ödülü\'nü kazanan ve "Altı Karakter Yazarını Arıyor" adlı başyapıtıyla modern Avrupa tiyatrosunda devrim yaratan İtalyan yazar kimdir?', 'Luigi Pirandello', ['Carlo Goldoni', 'Dario Fo', 'Gabriele D\'Annunzio'], 'Sicilya doğumlu Luigi Pirandello, gerçeklik, yanılsama ve kimlik parçalanması temalarıyla yirminci yüzyıl modernist tiyatrosunu derinden etkilemiştir.'),
  ('"Görünmez Kentler", "Bir Kış Gecesi Eğer Bir Yolcu" ve "Ağaca Tüneyen Baron" gibi eserleriyle tanınan postmodern İtalyan edebiyatının usta yazarı kimdir?', 'Italo Calvino', ['Umberto Eco', 'Alberto Moravia', 'Cesare Pavese'], 'Italo Calvino masalsı hayal gücü, yapısal oyunlar ve felsefi derinliği birleştiren eserleriyle yirminci yüzyıl dünya edebiyatının en özgün kalemlerindendir.'),
  ('Orta Çağ\'daki bir Benedikten manastırında işlenen gizemli cinayetleri konu alan "Gülün Adı" (Il nome della rosa) adlı dünyaca ünlü romanın İtalyan yazarı ve göstergebilimcisi kimdir?', 'Umberto Eco', ['Italo Svevo', 'Primo Levi', 'Dino Buzzati'], 'Göstergebilim ve Orta Çağ estetiği profesörü Umberto Eco, 1980\'de yayımladığı ilk romanı Gülün Adı ile hem akademik hem popüler büyük bir başarı kazanmıştır.'),
  ('Modern Avrupa romanının ilk büyük örneği kabul edilen "Don Kişot" (El ingenioso hidalgo Don Quijote de la Mancha) adlı ölümsüz eserin İspanyol yazarı kimdir?', 'Miguel de Cervantes Saavedra', ['Lope de Vega Carpio', 'Pedro Calderón de la Barca', 'Francisco de Quevedo'], 'Miguel de Cervantes\'in 1605 ve 1615 yıllarında iki cilt halinde yayımladığı Don Kişot, modern roman sanatının kurucu başyapıtıdır.'),
  ('Don Kişot\'un serüvenleri boyunca yanından ayırmadığı sadık silahtarı, sıska atı ve hayalinde soylu bir hanımefendiye dönüştürdüğü köylü kızı hangi seçenekte doğru sıralanmıştır?', 'Sancho Panza, Rocinante ve Tobosolu Dulcinea', ['Lazarillo, Babieca ve Segovialı Marcela', 'Basilio, Clavileño ve Sevillalı Dorotea', 'Cardenio, Bucéfalo ve Toledolu Luscinda'], 'Gerçekçi köylü Sancho Panza, yaşlı at Rocinante ve gerçekte Aldonza Lorenzo adlı bir köylü kızı olan Dulcinea, romanın en ünlü simgeleridir.'),
  ('İspanyol Altın Çağı (Siglo de Oro) tiyatrosunun kurucusu sayılan, yüzlerce oyun yazması nedeniyle Cervantes tarafından "Doğanın Harikası" (Monstruo de la Naturaleza) olarak nitelendirilen yazar kimdir?', 'Lope de Vega', ['Tirso de Molina', 'Juan Ruiz de Alarcón', 'Miguel de Unamuno'], 'Olağanüstü üretkenliğiyle yüzlerce komedya ve dinsel oyun kaleme alan Lope de Vega, İspanyol ulusal tiyatrosunun kurallarını belirlemiştir.'),
  ('İspanyol Barok tiyatrosunun en büyük ustası olan ve "Hayat Bir Rüyadır" (La vida es sueño) adlı felsefi oyunuyla dünya edebiyatı tarihine geçen yazar kimdir?', 'Pedro Calderón de la Barca', ['Lope de Rueda', 'Leandro Fernández de Moratín', 'José Zorrilla'], 'Lope de Vega\'nın başlattığı Altın Çağ tiyatrosunu derin felsefi ve teolojik boyutla taçlandıran Calderón de la Barca, İspanyol Barok sanatının zirvesidir.'),
  ('1936 yılında İspanya İç Savaşı\'nın başında kurşuna dizilerek öldürülen, "Çingene Romansları", "Kanlı Düğün" ve "Bernarda Alba\'nın Evi" eserlerinin dünyaca ünlü İspanyol şair ve oyun yazarı kimdir?', 'Federico García Lorca', ['Antonio Machado', 'Juan Ramón Jiménez', 'Miguel Hernández'], 'Endülüs kültürünü avangart imgelerle birleştiren 27 Kuşağı\'nın en parlak temsilcisi Federico García Lorca, otuz sekiz yaşında Granada yakınlarında katledilmiştir.'),
  ('Federico García Lorca\'nın ikinci kocasının cenazesinden sonra beş kızına sekiz yıl boyunca dış dünyaya kapalı katı bir yas ilan eden otoriter bir anneyi anlattığı son oyunu hangisidir?', 'Bernarda Alba\'nın Evi', ['Yerma', 'Bekar Kız Doña Rosita', 'Mariana Pineda'], 'Lorca\'nın öldürülmeden kısa süre önce 1936\'da tamamladığı Bernarda Alba\'nın Evi, toplumsal baskı ve otoriterliğin boğucu atmosferini sergiler.'),
  ('Dante Alighieri "İlahi Komedya"nın Cehennem bölümünün girişinde "İçeri girenler, dışarıda bırakın her türlü umudu!" yazısını nerede görür?', 'Cehennem Kapısı\'nın üzerinde', ['Acheron Irmağı\'ndaki kayıkta', 'Karanlık Orman\'daki bir kayada', 'Araf Dağı\'nın ilk basamağında'], 'Cehennem\'in üçüncü kantosunun başında Dante, Cehennem Kapısı\'nın üstündeki bu ünlü ve ürkütücü yazıtı okuyarak içeri adım atar.'),
  ('Dante, Guido Cavalcanti ve Guido Guinizelli gibi 13. yüzyıl sonu İtalyan şairlerinin kadını Tanrı\'ya ulaştıran melek yüzlü bir varlık (donna angelicata) olarak yücelttikleri şiir akımına ne ad verilir?', 'Dolce Stil Novo (Tatlı Yeni Üslup)', ['Marinismo (Barok Şiir Okulu)', 'Crepuscolarismo (Alacakaranlık Şiiri)', 'Ermetismo (Kapalı Şiir Akımı)'], 'Adını bizzat Dante\'nin Araf bölümünde koyduğu Dolce Stil Novo, soyluluğu kan bağında değil temiz yürekte arayan incelikli lirik şiir anlayışıdır.'),
  ('Dante, Petrarca ve Boccaccio üçlüsü 14. yüzyıl İtalyan edebiyatını zirveye taşıdıkları için edebiyat tarihinde hangi ortak unvanla anılırlar?', 'Üç Taç (Tre Corone)', ['Üç Silahşor (Tre Moschettieri)', 'Üç Hümanist (Tre Umanisti)', 'Üç Akademisyen (Tre Accademici)'], 'Toskana lehçesini büyük bir edebiyat diline dönüştüren Dante, Petrarca ve Boccaccio İtalyan kültür tarihinde "Tre Corone" (Üç Taç) olarak adlandırılır.'),
  ('Luigi Pirandello\'nun 1867 yılında dünyaya geldiği ve pek çok öyküsüyle oyununa keskin gelenekleri, tutkuları ve toplumsal mizahıyla sahne olan İtalya adası hangisidir?', 'Sicilya', ['Sardinya', 'Elba', 'Korsika'], 'Sicilya\'nın Agrigento (Girgenti) kentinde doğan Pirandello, "Kaos" adını taşıyan korulukta dünyaya gelmiş ve ada kültürünü evrensel tiyatroya taşımıştır.'),
  ('Italo Calvino\'nun İkinci Dünya Savaşı yıllarında İtalyan direniş hareketini (partizanları) küçük bir çocuğun masalsı ve saf gözünden anlattığı 1947 tarihli ilk romanı hangisidir?', 'Örümceklerin Yuvalandığı Patika', ['İkiye Bölünen Vikont', 'Marcovaldo ya da Kentte Mevsimler', 'Karga Sona Kaldı'], 'Calvino\'nun bizzat katıldığı partizan direnişinden izler taşıyan Örümceklerin Yuvalandığı Patika, kahramanlık söylemi yerine çocuk Pin\'in gözünden yeni-gerçekçi ama masalsı bir bakış sunar.'),
  ('Cervantes\'in "Don Kişot" romanındaki başkahraman, okuduğu şövalye kitaplarının etkisiyle kendine "Don Kişot" adını vermeden önce La Mancha\'nın bir köyünde hangi asıl adla yaşayan yoksul düşmüş bir taşra soylusudur (hidalgo)?', 'Alonso Quijano', ['Rodrigo Díaz de Vivar', 'Amadís de Gaula', 'Lazarillo de Tormes'], 'Romanın başında ve ölüm döşeğindeki uyanış sahnesinde asıl adının "İyi Yürekli Alonso Quijano" olduğu açıkça belirtilir.'),
  ('16. ve 17. yüzyıllarda Cervantes, Lope de Vega, Calderón, Quevedo ve Góngora gibi dev yazarların yetiştiği İspanya\'nın en parlak kültür ve sanat dönemine ne ad verilir?', 'Altın Çağ (Siglo de Oro)', ['Gümüş Çağ (Edad de Plata)', 'Aydınlanma Çağı (Ilustración)', 'Yeniden Fetih Çağı (Reconquista)'], 'İspanyol sanatında Rönesans ve Barok dönemlerini kapsayan yaklaşık yüz elli yıllık bu olağanüstü yaratıcılık evresi "Siglo de Oro" (Altın Çağ) olarak adlandırılır.'),
  ('Federico García Lorca, Rafael Alberti, Luis Cernuda ve Vicente Aleixandre gibi İspanyol şairlerin Barok şair Góngora\'nın ölümünün 300. yılı dolayısıyla 1927\'de bir araya gelerek oluşturdukları ünlü edebi topluluk hangisidir?', '27 Kuşağı (Generación del 27)', ['98 Kuşağı (Generación del 98)', '14 Kuşağı (Generación del 14)', 'Modernismo Hareketi'], 'İspanyol şiirinin "Gümüş Çağı"nı yaratan 27 Kuşağı, geleneksel Endülüs halk şiirini sürrealizm ve avangart imgelerle sentezlemiştir.'),
  ('Giovanni Boccaccio\'nun "Decameron" öykülerini anlatmak üzere vebadan kaçıp Floransa dışındaki tepelere sığınan on gencin oluşturduğu neşeli topluluğa İtalyan edebiyat geleneğinde hangi ad verilir?', 'Liete brigata', ['Accademia della Crusca', 'Scapigliatura Grubu', 'Gruppo 63 Topluluğu'], 'Yedi genç hanım (Pampinea, Fiammetta, Filomena, Emilia, Lauretta, Neifile, Elissa) ve üç genç bey (Panfilo, Filostrato, Dioneo) vebanın kaosuna karşı uyumlu "brigata" topluluğunu kurar.'),
  ('Gabriel García Márquez\'in "Yüzyıllık Yalnızlık" adlı romanında Buendía ailesinin yedi kuşağı boyunca olayların geçtiği kurgusal kasabanın adı nedir?', 'Macondo', ['Comala kasabası', 'Santa María kenti', 'Yoknapatawpha bölgesi'], 'Macondo, José Arcadio Buendía ve eşi Úrsula Iguarán tarafından kurulan ve romanın tüm olay örgüsüne ev sahipliği yapan kurgusal kasabadır.'),
  ('Jorge Luis Borges\'in zamanın doğrusal değil, sonsuz olasılıklara bölünen bir ağ olduğunu işlediği ünlü öyküsünün adı nedir?', 'Yolları Çatallanan Bahçe', ['Babil Kitaplığı ve Aynalar', 'Ölümsüz ve Kum Kitabı', 'Funes ya da Bellek'], '"Yolları Çatallanan Bahçe" (El jardín de los senderos que se bifurcan), Borges\'in 1941\'de yayımlanan ve "Ficciones" içinde yer alan en ünlü öykülerinden biridir.'),
  ('Gabriel García Márquez\'in işleneceği herkes tarafından bilinmesine rağmen engellenmeyen bir namus cinayetini konu aldığı kısa romanı hangisidir?', 'Kırmızı Pazartesi', ['Kolera Günlerinde Aşk', 'Yaprak Fırtınası', 'Albaya Mektup Yok'], '"Kırmızı Pazartesi" (Crónica de una muerte anunciada), Santiago Nasar\'ın Vicario kardeşler tarafından öldürülmesini tersine kronoloji ve gazetecilik üslubuyla anlatır.'),
  ('Jorge Luis Borges\'in başı ve sonu olmayan, sayfaları sonsuz sayıda olan gizemli bir cildi anlattığı öyküsü ve bu öykünün yer aldığı kitabın adı nedir?', 'Kum Kitabı', ['Alef ve Zahir', 'Brodie Raporu', 'Alçaklığın Evrensel Tarihi'], '1975 yılında yayımlanan "Kum Kitabı" (El libro de arena), bir İncil satıcısından alınan sonsuz sayfalı büyülü kitabı konu edinir.'),
  ('Latin Amerika edebiyatında sıradan gerçeklik ile olağanüstü ve fantastik unsurların doğal bir akış içinde iç içe sunulmasına dayanan edebi anlayış nasıl adlandırılır?', 'Büyülü gerçekçilik', ['Toplumcu gerçekçilik akımı', 'Bilinç akışı ve izlenimcilik', 'Varoluşçu gerçeküstücülük'], 'Büyülü gerçekçilik, mucizevi olayları gündelik yaşamın sıradan bir parçasıymış gibi yansıtan ve özellikle Latin Amerika "Boom" kuşağıyla özdeşleşen akımdır.'),
  ('1971 yılında Nobel Edebiyat Ödülü\'ne layık görülen ve "Yirmi Aşk Şiiri ve Umutsuz Bir Şarkı" adlı eseriyle dünya çapında tanınan Şilili şair kimdir?', 'Pablo Neruda', ['Octavio Paz Lozano', 'César Vallejo Mendoza', 'Nicolás Guillén Batista'], 'Asıl adı Ricardo Eliécer Neftalí Reyes Basoalto olan Pablo Neruda, 1924\'te yayımlanan bu eseriyle genç yaşta büyük ün kazanmış ve 1971\'de Nobel almıştır.'),
  ('Julio Cortázar\'ın okura hem düz sırayla hem de bölüm sonlarındaki yönerge tablosunu izleyerek sekerek okuma olanağı sunduğu ünlü deneysel romanı hangisidir?', 'Seksek', ['Mırıldandığım Öyküler', 'Takipçi ve Diğer Öyküler', 'Kronopların ve Famaların Öyküleri'], '1963\'te yayımlanan "Seksek" (Rayuela), Horacio Oliveira\'nın Paris ve Buenos Aires\'teki arayışını doğrusal olmayan bir kurguyla anlatır.'),
  ('Gabriel García Márquez hangi yıl Nobel Edebiyat Ödülü\'nü kazanmıştır?', '1982', ['1971 yılında', '1990 senesinde', '1998 tarihinde'], 'Kolombiyalı yazar Gabriel García Márquez, düşsel ile gerçek olanı birleştiren roman ve öyküleri nedeniyle 1982 yılında Nobel Edebiyat Ödülü\'ne değer görülmüştür.'),
  ('Jorge Luis Borges hangi ülkenin edebiyatının en önemli temsilcilerinden biridir ve uzun yıllar bu ülkenin Ulusal Kütüphanesi\'nin müdürlüğünü yapmıştır?', 'Arjantin', ['Kolombiya Cumhuriyeti', 'Meksika Birleşik Devletleri', 'Şili Cumhuriyeti'], 'Buenos Aires doğumlu olan Jorge Luis Borges, Arjantin edebiyatının simge ismidir ve 1955-1973 yılları arasında Arjantin Ulusal Kütüphanesi\'ni yönetmiştir.'),
  ('"Yüzyıllık Yalnızlık" romanında Macondo kasabasını eşi Úrsula Iguarán ile birlikte kuran ve simya deneylerine kapılan aile reisi kimdir?', 'José Arcadio Buendía', ['Albay Aureliano Buendía', 'Aureliano Babilonia', 'Arcadio Segundo Buendía'], 'José Arcadio Buendía, Çingene Melquíades\'in getirdiği mıknatıs ve büyüteç gibi icatlara tutkun olan, en sonunda kestane ağacına bağlanan kurucu atadır.'),
  ('Pablo Neruda\'nın İspanya İç Savaşı\'na tanıklığının ve arkadaşı Federico García Lorca\'nın öldürülmesinin etkisiyle toplumcu-politik şiire yöneldiği eseri hangisidir?', 'İspanya\'yı Kalbimde Taşıyorum', ['Yirmi Aşk Şiiri ve Umutsuz Bir Şarkı', 'Yüz Aşk Sonesi', 'Sorular Kitabı'], '"Yeryüzünde Konaklama"nın üçüncü cildinde yer alan "İspanya\'yı Kalbimde Taşıyorum" (España en el corazón, 1937), faşizme karşı direnişi ve şairin politik dönüşümünü simgeler.'),
  ('Octavio Paz hangi ülkenin yetiştirdiği en önemli şair ve denemecilerden biridir ve 1990 yılında Nobel Edebiyat Ödülü\'nü kazanmıştır?', 'Meksika', ['Peru Cumhuriyeti', 'Küba Cumhuriyeti', 'Venezüella Cumhuriyeti'], 'Meksikalı şair, denemeci ve diplomat Octavio Paz, hem modern şiiri hem de Meksika kimliği üzerine derinlikli denemeleriyle 1990\'da Nobel Edebiyat Ödülü\'nü almıştır.'),
  ('Octavio Paz\'ın Meksika halkının tarihini, maskelerini, ölüm algısını ve kültürel kimliğini çözümlediği 1950 tarihli dünyaca ünlü deneme kitabının adı nedir?', 'Yalnızlığın Dolambacı', ['Yay ve Lir', 'Çamur Çocuklar', 'Güneş Taşı'], '"Yalnızlığın Dolambacı" (El laberinto de la soledad), Meksika ulusal karakterini, "Pachuco" tipini, Ölüler Günü\'nü ve tarihsel travmaları inceleyen başyapıt bir denemedir.'),
  ('2010 yılında Nobel Edebiyat Ödülü\'nü kazanan ve "Kent ve Köpekler", "Teke Şenliği" gibi romanlarıyla tanınan Perulu yazar kimdir?', 'Mario Vargas Llosa', ['Juan Rulfo Vizcaíno', 'Carlos Fuentes Macías', 'Alejo Carpentier'], '1936 Arequipa doğumlu Perulu yazar Mario Vargas Llosa, iktidar yapılarını haritalandıran ve bireyin direnişini işleyen romanlarıyla 2010 Nobel Edebiyat Ödülü\'nü almıştır.'),
  ('Yalnızca bir kısa roman ve bir öykü kitabı yayımlamasına karşın Latin Amerika edebiyatını derinden etkileyen ve "Pedro Páramo" adlı başyapıtı yazan Meksikalı yazar kimdir?', 'Juan Rulfo', ['Mariano Azuela', 'Carlos Fuentes', 'Juan José Arreola'], 'Juan Rulfo (1917-1986), "Ova Alev Alev" (1953) adlı öykü kitabı ve "Pedro Páramo" (1955) adlı kısa romanıyla modern Meksika ve Latin Amerika edebiyatının temel taşlarından biri olmuştur.'),
  ('Juan Rulfo\'nun "Pedro Páramo" romanında ölmüş annesi Dolores Preciado\'ya verdiği sözü tutmak için babasını aramak üzere Comala\'ya giden anlatıcı kimdir?', 'Juan Preciado', ['Miguel Páramo', 'Peder Rentería', 'Abundio Martínez'], 'Roman, Juan Preciado\'nun "Comala\'ya geldim, çünkü bana babamın burada yaşadığını söylediler, Pedro Páramo adında birinin" cümlesiyle açılır.'),
  ('1998 yılında Nobel Edebiyat Ödülü\'nü kazanarak bu ödülü alan ilk Portekiz dili yazarı olan ve "Körlük" romanıyla tanınan yazar kimdir?', 'José Saramago', ['Fernando Pessoa', 'Eça de Queirós', 'António Lobo Antunes'], '1922 Azinhaga doğumlu Portekizli yazar José Saramago, tarihsel ve alegorik romanlarıyla 1998 yılında Nobel Edebiyat Ödülü\'ne layık görülmüştür.'),
  ('José Saramago\'nun "Körlük" romanında trafik ışığında bekleyen ilk hastayla başlayan ve bütün kente yayılan salgın, hastaların gözünü nasıl bir renkle kaplamaktadır?', 'Süt beyazı bir parlaklık', ['Zifiri siyah bir karanlık', 'Kızıl bir sis tabakası', 'Kurşuni gri bir perde'], 'Romandaki gizemli "beyaz körlük" (resplandor branco), alışılmış karanlığın aksine hastaları süt denizine düşmüşçesine parlak bir beyazlığın içine hapseder.'),
  ('José Saramago\'nun "Körlük" romanında salgın boyunca görme yetisini kaybetmeyen, ancak kocasından ayrılmamak için kör taklidi yaparak karantinaya giren tek karakter kimdir?', 'Doktorun karısı', ['Koyu renk gözlüklü genç kız', 'İlk kör olan adamın eşi', 'Tek gözü bantlı yaşlı adam'], 'Göz doktorunun karısı, tüm kent körleşirken görebilen tek kişidir ve karantina koğuşundaki dehşete doğrudan tanıklık ederek grubun hayatta kalmasını sağlar.'),
  ('José Saramago\'nun romanlarında ilk bakışta fark edilen en belirgin biçimsel ve dilbilgisel üslup özelliği nedir?', 'Tırnak işareti ve soru işareti kullanmadan diyalogları yalnızca virgül ve büyük harf geçişleriyle uzun paragraflarda akıtması', ['Her cümleyi en fazla beş kelimelik telgraf ifadeleriyle kurup sıfatları tamamen metinden çıkarması', 'Karakter konuşmalarını tiyatro teksti gibi satır başlarında isim ve iki nokta üst üste koyarak ayırması', 'Romanın her bölümünü farklı bir Avrupa dilinde yazıp sayfa altlarına Portekizce çeviri eklemesi'], 'Saramago, sözlü anlatı ritmini yakalamak için standart noktalama işaretlerinin çoğunu terk eder; konuşmacı değişimlerini virgül sonrası büyük harfle başlatır.'),
  ('Portekiz edebiyatının en büyük modern şairlerinden biri olan ve yaşamı boyunca "heteronim" adı verilen kurgusal şair kişilikler yaratarak eser veren yazar kimdir?', 'Fernando Pessoa', ['José Saramago', 'Luís de Camões', 'Camilo Castelo Branco'], '1888 Lizbon doğumlu Fernando Pessoa, yalnızca takma ad değil, her birinin ayrı biyografisi, felsefesi ve üslubu olan onlarca "heteronim" (dış-benlik) yaratmıştır.'),
  ('Fernando Pessoa\'nın Lizbon\'da yaşayan yardımcı muhasebeci "yarı-heteronimi" Bernardo Soares kimliğiyle kaleme aldığı, ölümünden çok sonra yayımlanan başyapıtı hangisidir?', 'Huzursuzluğun Kitabı', ['Anarşist Banker', 'Mesaj', 'Deniz Övgüsü'], '1982\'de ilk kez kitaplaştırılan "Huzursuzluğun Kitabı" (Livro do Desassossego), Lizbon sokaklarında yürüyen Bernardo Soares\'in varoluşsal fragmanlarından oluşur.'),
  ('José Saramago\'nun "Körlük" romanından dört yıl sonra aynı isimsiz başkentte yapılan seçimlerde halkın yüzde seksen üçünün beyaz (boş) oy kullanmasını anlattığı devam niteliğindeki romanı hangisidir?', 'Görmek', ['Ölüm Bir Varmış Bir Yokmuş', 'Kabil', 'Mağara'], '2004\'te yayımlanan "Görmek" (Ensaio sobre a Lucidez), boş oy krizi karşısında paniğe kapılan hükümetin dört yıl önceki beyaz körlük vakasını ve doktorun karısını hedef almasını işler.'),
  ('Fernando Pessoa\'nın hayattayken Portekizce olarak yayımlanan tek şiir kitabı olan ve Portekiz\'in denizcilik tarihini mistik-sembolik bir dille yorumlayan eseri hangisidir?', 'Mesaj', ['Tütün Dükkanı', 'Sürü Güdücüsü', 'Şeytanın Saati'], '1934\'te yayımlanan "Mesaj" (Mensagem), Portekiz\'in keşifler çağını ve "Beşinci İmparatorluk" mitini okült ve ulusal-mistik sembollerle ele alır.'),
  ('José Saramago\'nun "Körlük" romanında özel kişi adlarına ve kent ismine hiç yer vermeyip karakterleri "göz doktoru", "koyu renk gözlüklü kız" gibi betimlemelerle anmasının temel nedeni nedir?', 'Anlatıyı belirli bir coğrafyadan çıkarıp insan doğasının ve uygarlığın kırılganlığı üzerine evrensel bir alegoriye dönüştürmek', ['Portekiz sansür kurulunun gerçek siyasetçilerle benzerlik kurulmasını yasaklayan yasasından korunmak', 'Salgın nedeniyle tüm nüfus kayıtlarının yanması sonucu karakterlerin kendi adlarını fiziksel olarak unutması', 'Polisiye bir gizem yaratarak romanın son sayfasında karakterlerin gerçek kimliklerini okura sürpriz olarak açıklamak'], 'İsimlerin silinmesi hem körleşen dünyada kimliklerin yitimini yansıtır hem de her toplumda yaşanabilecek ahlaki çöküşü evrenselleştirir.'),
  ('1960\'lar ve 1970\'lerde Gabriel García Márquez, Julio Cortázar, Mario Vargas Llosa ve Carlos Fuentes gibi yazarların eserleriyle Latin Amerika edebiyatının dünya çapında patlama yaptığı döneme ne ad verilir?', 'Latin Amerika Boom Kuşağı', ['Kayıp Kuşak Hareketi', 'Beat Kuşağı Akımı', '98 Kuşağı Edebiyatı'], '"Latin Amerika Boom" (El Boom Latinoamericano), yenilikçi anlatı teknikleri ve büyülü gerçekçilikle kıta edebiyatını küresel merkeze taşıyan edebi harekettir.'),
  ('Pablo Neruda\'nın Şili kıyısında Pasifik Okyanusu\'na bakan, gemi başı figürleri ve deniz kabukları koleksiyonlarıyla ünlü evinin bulunduğu ve şiirlerine de adını veren yerleşim yeri neresidir?', 'Isla Negra', ['Valparaíso Tepesi', 'Punta Arenas', 'Antofagasta'], 'Gerçekte bir ada olmayan ancak kıyıdaki siyah kayalıklardan adını alan Isla Negra (Kara Ada), Neruda\'nın en sevdiği evine ev sahipliği yapar ve "Isla Negra Anıları" eserine adını verir.'),
  ('1994 yapımı ünlü İtalyan filmi "Postacı"da (Il Postino), sürgünde yaşadığı adada bisikletli postacı Mario\'ya şiir ve metaforun ne olduğunu öğreten gerçek şair kimdir?', 'Pablo Neruda', ['Octavio Paz', 'Jorge Luis Borges', 'Fernando Pessoa'], 'Antonio Skármeta\'nın "Ateşli Sabır" (Ardiente paciencia) adlı romanından uyarlanan film, Pablo Neruda\'nın İtalya sürgünündeki yıllarını ve sıradan bir postacıyla dostluğunu konu alır.'),
  ('Julio Cortázar Arjantinli bir ailenin çocuğu olarak hangi Avrupa başkentinde dünyaya gelmiş ve yaşamının son otuz küsur yılını da hangi Avrupa başkentinde geçirmiştir?', 'Brüksel\'de doğmuş, Paris\'te yaşamıştır', ['Madrid\'de doğmuş, Roma\'da yaşamıştır', 'Lizbon\'da doğmuş, Londra\'da yaşamıştır', 'Cenevre\'de doğmuş, Berlin\'de yaşamıştır'], 'Cortázar babasının diplomatik görevi sırasında 1914\'te Brüksel\'de doğmuş, Arjantin\'de büyümüş ve 1951\'de yerleştiği Paris\'te 1984 yılındaki ölümüne dek yaşamıştır.'),
  ('Fernando Pessoa\'nın "Huzursuzluğun Kitabı"nda Bernardo Soares\'in çalıştığı ve penceresinden Lizbon\'un gündelik akışını seyrettiği ünlü sokağın adı nedir?', 'Douradores Sokağı', ['Alcala Caddesi', 'Florida Sokağı', 'Corrientes Bulvarı'], 'Bernardo Soares kendisini "Douradores Sokağı\'ndaki kumaş deposunun yardımcı muhasebecisi" olarak tanımlar; tüm varoluşsal evrenini bu dar Lizbon sokağından kurar.'),
  ('Pablo Neruda\'nın gerçek adı olan Ricardo Eliécer Neftalí Reyes Basoalto yerine babasının tepkisinden çekinerek genç yaşta seçtiği "Neruda" soyadını hangi ülke edebiyatından bir şair ve yazardan ödünç aldığı kabul edilir?', 'Çek yazar Jan Neruda\'dan', ['Rus şair Aleksandr Puşkin\'den', 'Macar şair Sándor Petőfi\'den', 'Polonyalı şair Adam Mickiewicz\'ten'], 'Genç Reyes, şiir yazmasını onaylamayan demiryolu işçisi babasından gizlenmek için 19. yüzyıl Çek şair ve öykücüsü Jan Neruda\'nın soyadını mahlas olarak benimsemiştir ve daha sonra yasal adı yapmıştır.'),
  ('José Saramago\'nun "İsa\'ya Göre İncil" romanına Portekiz hükümetinin Avrupa Edebiyat Ödülü adaylığında sansür ve veto uygulaması üzerine yazar yaşamının kalan kısmını geçirmek üzere hangi adaya yerleşmiştir?', 'Kanarya Adaları\'ndaki Lanzarote Adası\'na', ['Akdeniz\'deki Sicilya Adası\'na', 'Ege Denizi\'ndeki Girit Adası\'na', 'Karayipler\'deki Küba Adası\'na'], '1992\'de dönemin muhafazakar Portekiz hükümetinin romanını veto etmesini protesto eden Saramago, eşi Pilar del Río ile birlikte İspanya\'ya bağlı Lanzarote Adası\'na taşınmış ve "Lanzarote Günlükleri"ni orada yazmıştır.'),
  ('Pablo Neruda ülkesi Şili\'yi yıllarca çeşitli Asya, Avrupa ve Amerika kentlerinde hangi resmi görevle temsil etmiştir?', 'Konsolos ve Büyükelçi', ['Deniz Kuvvetleri Amirali', 'Yüksek Mahkeme Başsavcısı', 'Merkez Bankası Başkanı'], 'Neruda genç yaşta Burma (Myanmar), Seylan, Cava, Barselona, Madrid ve Meksika\'da konsolosluk yapmış; Salvador Allende döneminde ise Paris Büyükelçisi olarak görev almıştır.'),
  ('Octavio Paz da tıpkı Pablo Neruda gibi uzun yıllar ülkesini dış temsilciliklerde hangi görevle temsil etmiş ve bu sayede Fransız gerçeküstücüleri ile Hint felsefesini yerinde tanımıştır?', 'Diplomat ve Büyükelçi', ['Arkeoloji Müzesi Müdürü', 'Askeri Ataşe ve Kurmay Albay', 'Uluslararası Ticaret Hakemi'], 'Octavio Paz 1945\'te Meksika Dışişleri\'ne girerek Paris, Tokyo ve Cenevre\'de diplomatlık, Yeni Delhi\'de ise Büyükelçilik yapmıştır.'),
  ('Kristiania sokaklarında yoksulluk ve açlıkla boğuşan genç bir yazar adayının ruhsal sarsıntılarını anlatan "Açlık" romanının Norveçli yazarı kimdir?', 'Knut Hamsun', ['Henrik Ibsen', 'Bjørnstjerne Bjørnson', 'Sigrid Undset'], '"Açlık" (Sult), 1890 yılında Knut Hamsun tarafından yayımlanmış psikolojik edebiyatın öncü yapıtlarındandır.'),
  ('Knut Hamsun\'un değirmencinin oğlu Johannes ile şato sahibinin kızı arasındaki imkânsız aşkı lirik bir dille anlattığı ünlü romanı hangisidir?', 'Viktoria', ['Toprağın Bereketi', 'Açlık', 'Serserilik Günleri'], '1898\'de yayımlanan "Viktoria", sınıf farkı yüzünden kavuşamayan Johannes ve Viktoria\'nın trajik aşkını konu alır.'),
  ('Selma Lagerlöf\'ün İsveç coğrafyasını çocuklara tanıtmak amacıyla kaleme aldığı, yaban kazlarıyla ülkeyi dolaşan küçülmüş bir çocuğun masalsı serüveni hangisidir?', 'Nils Holgersson\'un Harika Yolculuğu', ['Gösta Berling Efsanesi', 'Kudüs', 'Portugallia İmparatoru'], '"Nils Holgersson\'un Harika Yolculuğu", cüceye dönüşen yaramaz Nils\'in kaz Akka ve sürüsüyle İsveç\'i gezmesini anlatır.'),
  ('"Çirkin Ördek Yavrusu", "Kibritçi Kız" ve "Küçük Deniz Kızı" gibi dünyaca ünlü masalların Danimarkalı yazarı kimdir?', 'Hans Christian Andersen', ['Søren Kierkegaard', 'Jacob Grimm', 'Henrik Pontoppidan'], '19. yüzyıl Danimarka edebiyatının en tanınmış ismi Hans Christian Andersen, modern edebi masal türünün ustasıdır.'),
  ('Hans Christian Andersen\'in yılbaşı gecesi soğuktan donmamak için elindeki kibritleri birer birer yakarak güzel hayaller gören yoksul çocuğu anlattığı masal hangisidir?', 'Kibritçi Kız', ['Karlar Kraliçesi', 'Parmak Kız', 'Kurşun Asker'], '"Kibritçi Kız", Viktorya çağı Avrupa\'sındaki çocuk yoksulluğunu ve toplumsal duyarsızlığı trajik biçimde yansıtır.'),
  ('Osmanlı Sadrazamı Sokollu Mehmed Paşa tarafından Vişegrad\'da yaptırılan köprü etrafında dört yüzyıllık tarihi anlatan "Drina Köprüsü" romanının Nobel ödüllü yazarı kimdir?', 'İvo Andrić', ['Meşa Selimoviç', 'Miroslav Krleža', 'Danilo Kiš'], 'Yugoslav (Bosnalı/Sırp-Hırvat) yazar İvo Andrić, 1961 yılında "Drina Köprüsü" başta olmak üzere epik eserleriyle Nobel kazanmıştır.'),
  ('Girit adasında bir linyit madeni işletmeye giden kitabi aydın anlatıcı ile yaşam sevinciyle dolu Makedonyalı işçinin dostluğunu anlatan "Zorba" romanının Yunan yazarı kimdir?', 'Nikos Kazancakis', ['Konstantinos Kavafis', 'Yorgos Seferis', 'Odiseas Elitis'], '"Aleksi Zorba" (Vios kai Politeia tou Alexi Zorba), Giritli ünlü yazar Nikos Kazancakis\'in en bilinen başyapıtıdır.'),
  ('Nikos Kazancakis\'in "Zorba" romanında Aleksi Zorba\'nın yanından hiç ayırmadığı ve duygularını ifade etmek için tutkuyla çaldığı müzik aleti nedir?', 'Santur', ['Buzuki', 'Kemençe', 'Klarnet'], 'Roman boyunca Zorba\'nın ruhunun ayrılmaz bir parçası olan ve kılıfından özenle çıkardığı çalgı santurdur (santouri).'),
  ('2005 yılında Uluslararası Man Booker Ödülü\'nü kazanan, "Ölü Ordunun Generali" ve "Taş Kentin Kroniği" gibi eserleriyle tanınan Arnavut yazar kimdir?', 'İsmail Kadare', ['Fatos Kongoli', 'Dritëro Agolli', 'Gjergj Fishta'], 'Çağdaş Arnavut edebiyatının dünyaca tanınan en büyük temsilcisi İsmail Kadare, ilk Uluslararası Man Booker Ödülü\'nün sahibidir.'),
  ('Ömer Hayyam\'ın el yazması "Rubaiyat" eserinin 11. yüzyıldan 20. yüzyıl başlarına uzanan serüvenini anlatan "Semerkant" romanının Lübnan asıllı Fransız yazarı kimdir?', 'Amin Maalouf', ['Halil Cibran', 'Mihail Nuayme', 'Adonis'], 'Fransız Akademisi üyesi Lübnanlı yazar Amin Maalouf, 1988\'de yayımladığı "Semerkant" ile dünya çapında büyük ün kazanmıştır.'),
  ('Amin Maalouf\'un 16. yüzyılda Granada\'nın düşüşünden sonra Akdeniz havzasını dolaşan Hasan el-Vezzan\'ın yaşamını anlattığı ünlü tarihsel romanı hangisidir?', 'Afrikalı Leo', ['Tanios Kayası', 'Işık Bahçeleri', 'Yüzüncü Ad'], '1986 tarihli "Afrikalı Leo" (Léon l\'Africain), Endülüs\'ten Fas, Kahire ve Roma\'ya savrulan gezgin Hasan el-Vezzan\'ın kurgusal anılarıdır.'),
  ('Necib Mahfuz\'un Kahire\'nin eski mahallelerindeki kahvehaneleri, sokakları ve dar gelirli insanlarını gerçekçi biçimde betimlemesi nedeniyle edebiyat eleştirmenlerince hangi Batılı ustaya benzetildiği bilinir?', 'Honoré de Balzac', ['Franz Kafka', 'James Joyce', 'Samuel Beckett'], 'Mahfuz, Kahire toplumunun tüm katmanlarını panoramik ve gerçekçi bir gözle kayıt altına aldığı için "Arap edebiyatının Balzac\'ı" olarak anılmıştır.'),
  ('Andersen\'in yirmi döşek ve yirmi kuş tüyü yorganın altına konulan küçücük bir taneyi hissederek gerçek soyluluğunu kanıtlayan genç kızı anlattığı nükteli masal hangisidir?', 'Prenses ve Bezelye Tanesi', ['Parmak Kız', 'Uçan Sandık', 'Çirkin Ördek Yavrusu'], '"Prenses ve Bezelye Tanesi", aşırı duyarlılık kavramını ince bir ironiyle ele alan kısa ve ünlü bir Andersen masalıdır.'),
  ('"Gün Olur Asra Bedel", "Cemile", "Beyaz Gemi" ve "Selvi Boylum Al Yazmalım" gibi unutulmaz eserleriyle dünya edebiyatına geçen büyük Kırgız yazar kimdir?', 'Cengiz Aytmatov', ['Muhtar Avezov', 'Olcas Süleymenov', 'Abdulla Kadiri'], 'Kırgız edebiyatının ve Türk dünyasının en büyük çağdaş yazarlarından Cengiz Aytmatov, eserleriyle evrensel bir üne kavuşmuştur.'),
  ('Cengiz Aytmatov\'un "Gün Olur Asra Bedel" romanında Boranlı istasyonunda çalışan Yedigey\'in, vasiyeti üzerine Ana-Beyit mezarlığına gömmek için götürdüğü merhum dostu kimdir?', 'Kazangap', ['Sabitcan', 'Abutalip', 'Danyar'], 'Romanın ana kurgusu, demiryolu işçisi Boranlı Yedigey\'in emektar dostu Kazangap\'ı Ana-Beyit\'e defnetmek üzere çıktığı bir günlük yolculuktur.'),
  ('Fransız şair Louis Aragon\'un "Dünyanın en güzel aşk hikâyesi" olarak nitelendirdiği, Cengiz Aytmatov\'a uluslararası ün kazandıran uzun öyküsü hangisidir?', 'Cemile', ['Beyaz Gemi', 'İlk Öğretmen', 'Yüz Yüze'], '1958\'de yayımlanan ve Aragon tarafından Fransızcaya çevrilen "Cemile", Aytmatov\'un adını tüm dünyaya duyuran lirik başyapıtıdır.'),
  ('Cengiz Aytmatov\'un "Selvi Boylum Al Yazmalım" (Kırmızı Eşarp) adlı eserinde kamyon şoförü İlyas ile Asel\'in fırtınalı aşkının ardından Asel\'e ve çocuğuna şefkatle sahip çıkan emekçi karakter kimdir?', 'Baytemir', ['Alibek', 'Canbolat', 'Momun'], 'Yol bakım ustası Baytemir, İlyas\'ın terk ettiği Asel ve küçük Samet\'e gerçek bir aile sıcaklığı ve sarsılmaz bir güven sunar.'),
  ('Cengiz Aytmatov\'un Issık Gölü kıyısındaki ıssız bir orman gözetleme evinde dedesiyle yaşayan isimsiz küçük bir çocuğun acı sonla biten masalsı dünyasını anlattığı eseri hangisidir?', 'Beyaz Gemi', ['Elveda Gülsarı', 'Dişi Kurdun Rüyaları', 'Toprak Ana'], '1970 tarihli "Beyaz Gemi", dürbünüyle göldeki beyaz gemiyi izleyen ve balığa dönüşüp gemideki babasına yüzmeyi hayal eden çocuğun öyküsüdür.'),
  ('Cengiz Aytmatov\'un İkinci Dünya Savaşı\'nda eşini ve üç oğlunu cephede yitiren Tolgonay adlı Kırgız kadınının acılarını tarlayla dertleşerek anlattığı eseri hangisidir?', 'Toprak Ana', ['İlk Öğretmen', 'Deve Gözü', 'Yüzyüze'], '"Toprak Ana"da savaşın geride kalan kadınlar üzerindeki ağır yükü, Tolgonay ile Toprak Ana arasındaki diyaloglarla destansılaşır.'),
  ('"Bir ananın iki oğlu, bir amalın iki kolu / O da ulu, bu da ulu / Azerbaycan-Türkiye" dizeleriyle iki ülkenin kardeşliğini ölümsüzleştiren büyük Azerbaycan şairi kimdir?', 'Bahtiyar Vahabzade', ['Samed Vurgun', 'Resul Rıza', 'Hüseyin Cavid'], 'Çağdaş Azerbaycan şiirinin ve milli bağımsızlık ruhunun en gür sesi olan Bahtiyar Vahabzade (1925-2009), "Azerbaycan-Türkiye" şiiriyle gönüllerde yer etmiştir.'),
  ('Çocukluk yıllarını geçirdiği köydeki dağı muhatap alarak Azerbaycan Türkçesiyle yazdığı "Heyder Babaya Selam" şiiriyle tüm Türk dünyasında yankı uyandıran Tebrizli büyük şair kimdir?', 'Muhammed Hüseyin Şehriyar', ['Fuzuli', 'İmadeddin Nesimi', 'Şah İsmail Hatayi'], '1906 Tebriz doğumlu Muhammed Hüseyin Behcet-i Tebrizi (Şehriyar), "Heyder Babaya Selam" ile Güney Azerbaycan edebiyatında çığır açmıştır.'),
  ('Şehriyar\'ın "Heyder Babaya Selam" adlı ölümsüz manzumesine adını veren "Heyder Baba" gerçekte nedir?', 'Şairin çocukluğunun geçtiği Hoşginab köyünün karşısında yükselen bir dağ', ['Tebriz çarşısında halı dokuyan yüz yaşındaki bilge bir usta', 'Safevi döneminden kalma tarihi bir kervansaray ve medrese', 'Kafkas dağlarından Hazar Denizi\'ne dökülen coşkun bir nehir'], '"Heyder Baba", Tebriz yakınlarındaki Karaçemen bölgesinde, şairin çocukluk anılarının mekânı olan Hoşginab (Kayışkuran) köyüne bakan dağdır.'),
  ('Knut Hamsun\'un "Açlık" romanının geçtiği ve 1925 yılından itibaren adı "Oslo" olarak değiştirilen Norveç\'in başkenti eserde hangi tarihsel adıyla anılır?', 'Kristiania', ['Bergen', 'Trondheim', 'Stavanger'], 'Romanın ilk cümlesinde "O günlerde, açlıktan kıvranarak dolaştığım Kristiania\'da, bu garip kentte..." denilerek Oslo\'nun eski adı kullanılır.'),
  ('Nikos Kazancakis\'in "Zorba" romanında Girit köylüleri tarafından taşlanarak öldürülen genç dul kadını korumaya çalışan tek kişinin Aleksi Zorba olması onun hangi yönünü gösterir?', 'Toplumsal linç kültürüne ve bağnazlığa karşı merhameti ve bireysel cesareti savunan şövalye ruhunu', ['Köy muhtarlığı seçimlerinde kadın seçmenlerin oylarını kazanmaya yönelik politik hesabını', 'Maden ocağındaki işçilerin dikkatini dağıtarak çalışma saatlerini uzatma kurnazlığını', 'Girit dışından gelen yabancı tüccarlarla gizli ortaklık kurma arzusunu'], 'Anlatıcı korkudan donakalırken Zorba bıçağını çekip kalabalığın önüne atılır; bu sahne Zorba\'nın eylemci vicdanını gösterir.'),
  ('Cengiz Aytmatov\'un "Beyaz Gemi" romanındaki küçük çocuğun okula başlamak için büyük bir heyecanla beklediği ve kendisini yapayalnız hissettiğinde içi boş bir arkadaş gibi konuştuğu nesne nedir?', 'Okul çantası', ['Tahta kılıç', 'Cep saati', 'Kırmızı bisiklet'], 'Dedesinin kasabadan aldığı "okul çantası", yalnız çocuğun en yakın sırdaşı olur ve çocuk masallarını bile çantasına anlatır.'),
  ('Knut Hamsun, Selma Lagerlöf, İvo Andrić ve Necib Mahfuz dörtlüsünün tamamı için geçerli olan ortak uluslararası edebiyat başarısı aşağıdakilerden hangisidir?', 'Dördünün de Nobel Edebiyat Ödülü\'ne layık görülmüş olmaları', ['Dördünün de eserlerini yalnızca Fransızca olarak kaleme almaları', 'Dördünün de aynı yıl içinde doğup aynı edebi toplulukta yer almaları', 'Dördünün de yalnızca çocuklar için hayvan masalları yazmış olmaları'], 'Lagerlöf (1909), Hamsun (1920), Andrić (1961) ve Mahfuz (1988) Nobel Edebiyat Ödülü kazanmış büyük yazarlardır.'),
];
